donut<-function(values,labels,colors,tag,explode=NULL,center=NULL){
 dd<-data.frame(category=labels,amount=values,share=values/sum(values),explode=if(is.null(explode))0 else explode);dd$mid<-2*pi*(cumsum(dd$share)-dd$share/2)
 dd$label<-paste0(values,'%');dd$radius<-ifelse(dd$amount<=3,1.45,1.05);dd$x<-dd$radius*sin(dd$mid);dd$y<-dd$radius*cos(dd$mid)
 z<-ggplot(dd)+geom_arc_bar(aes(x0=0,y0=0,r0=.48,r=1.48,amount=amount,fill=category,explode=explode),stat='pie',sep=.018,color='white',linewidth=.28)+geom_text(aes(x=x,y=y,label=label),size=7/2.845,family='Arial')+scale_fill_manual(values=setNames(colors,labels))+coord_fixed(xlim=c(-1.85,1.85),ylim=c(-1.8,1.8),clip='off')+labs(tag=tag)+theme_void(base_family='Arial',base_size=7)+theme(legend.position='none',plot.margin=margin(2,2,2,2),plot.tag=element_text(size=9,face='bold'))
 if(!is.null(center))z<-z+annotate('text',x=0,y=0,label=center,size=7/2.845,family='Arial');list(plot=z,data=dd)
}
