# ASF-V12: synthetic contrast fixture, with full upper/lower/composition topology.
land<-c('Urban residential land','Industrial land','Commercial service land','Cultural and science land','Transportation hubs','Institution land','Higher education land','Public utility land','Rural residential land','Port terminal land')
abbr<-function(x)vapply(x,function(z)paste(strwrap(z,width=20),collapse='\n'),character(1));dd<-expand.grid(land=land,sex=c('Women','Men'),day=c('Weekday','Weekend'),stringsAsFactors=FALSE);base<-setNames(c(.22,.12,.085,.041,.012,.010,.011,.007,.006,.002),land);dd$value<-pmax(.0005,base[dd$land]*runif(nrow(dd),.67,1.22));dd$offset<-c(-.3,-.1,.1,.3)[match(paste(dd$day,dd$sex),c('Weekday Women','Weekday Men','Weekend Women','Weekend Men'))];sc<-c(Women='#9D5B89',Men='#2B8792')
lolli<-function(names,tag,upper){z<-dd[dd$land%in%names,];z$x<-match(z$land,names)+z$offset;ggplot(z,aes(x,value,color=sex))+geom_segment(aes(xend=x,y=0,yend=value),color='#ADB4BA',linetype='dotted',linewidth=.4)+geom_point(aes(fill=sex,shape=day),size=2.5,stroke=.8)+scale_color_manual(values=sc)+scale_fill_manual(values=sc)+scale_shape_manual(values=c(Weekday=21,Weekend=1))+scale_x_continuous(breaks=seq_along(names),labels=abbr(names),expand=expansion(add=.6))+scale_y_continuous(limits=c(0,upper),expand=c(0,0))+labs(x=NULL,y='Population index',tag=tag,color=NULL,fill=NULL,shape=NULL)+bt+theme(legend.position='top',legend.box='vertical',legend.margin=margin(0,0,0,0),legend.spacing=unit(0,'mm'))}
high<-lolli(land[1:3],'a',.30)+scale_x_continuous(breaks=1:3,labels=vapply(land[1:3],function(z)paste(strwrap(z,width=14),collapse='\n'),character(1)),expand=expansion(add=.6))+guides(shape=guide_legend(override.aes=list(shape=c(21,1),fill=c('#555555',NA),colour=c('#555555','#555555'))));low<-lolli(land[4:10],'c',.055)+theme(legend.position='none')
ss<-expand.grid(land=land,day=c('Weekday','Weekend'),component=c('More women','Equilibrium','More men'),stringsAsFactors=FALSE);ss$value<-0
for(a in land)for(b in c('Weekday','Weekend')){ix<-which(ss$land==a&ss$day==b);v<-rgamma(3,shape=c(3,2,4));ss$value[ix]<-v/sum(v)*100}
ss$component<-factor(ss$component,levels=c('More women','Equilibrium','More men'));ss$land<-factor(ss$land,levels=rev(land));ss$y<-as.numeric(ss$land)
ss<-ss[order(ss$day,ss$y,ss$component),];ss$end<-ave(ss$value,interaction(ss$day,ss$land),FUN=cumsum);ss$start<-ss$end-ss$value;stopifnot(all(ss$end<=100+1e-10));ss$end<-pmin(100,ss$end);ss$start<-pmax(0,ss$start)
conn<-do.call(rbind,lapply(split(ss,ss$day),function(z){do.call(rbind,lapply(1:2,function(k){zz<-z[as.numeric(z$component)==k,];zz<-zz[order(zz$y),];data.frame(day=zz$day[-nrow(zz)],x=head(zz$end,-1),xend=tail(zz$end,-1),y=head(zz$y,-1)+.34,yend=tail(zz$y,-1)-.34)}))}))
st<-ggplot(ss)+geom_segment(data=conn,aes(x=x,xend=xend,y=y,yend=yend),color='#63696E',linewidth=.25)+geom_rect(aes(xmin=start,xmax=end,ymin=y-.34,ymax=y+.34,fill=component),color='#50575D',linewidth=.22)+geom_text(data=ss[ss$value>=8,],aes(x=(start+end)/2,y=y,label=paste0(round(value),'%')),size=7/2.845,family='Arial')+facet_grid(.~day)+scale_fill_manual(values=c('More women'=sc['Women'],'Equilibrium'='#D1D5D8','More men'=sc['Men']))+scale_x_continuous(limits=c(0,100),breaks=c(0,50,100),expand=c(0,0))+scale_y_continuous(breaks=1:10,labels=abbr(rev(land)),expand=expansion(add=.45))+labs(x=NULL,y=NULL,fill=NULL,tag='b')+bt+theme(legend.position='top',legend.direction='horizontal',legend.key.width=unit(2.5,'mm'),legend.spacing.x=unit(.4,'mm'),strip.background=element_blank(),strip.text=element_text(size=7))
# Explicit unname avoids nested color names in manual scales.
st<-st+scale_fill_manual(values=c('More women'=unname(sc['Women']),'Equilibrium'='#D1D5D8','More men'=unname(sc['Men'])))
upper<-wrap_plots(list(high,st),ncol=2,widths=c(1,1.8));plot<-wrap_plots(list(upper,low),ncol=1,heights=c(1.5,1))
