# SCICASE-126: native circlize, feature links derived from repeated IDs only.
library(circlize);groups<-sprintf('Trait %02d',1:12);circ<-do.call(rbind,lapply(seq_along(groups),function(i){n<-24;data.frame(group=groups[i],feature=sprintf('F%02d',((seq_len(n)+i*3-2)%%48)+1),x=(seq_len(n)-.5)/n,score=sort(runif(n,.02,.98),decreasing=TRUE),class=sample(c('Class A','Class B'),n,replace=TRUE))}));circ$color<-ifelse(circ$class=='Class A','#386A8C','#D58A73')
labels<-do.call(rbind,lapply(split(circ,circ$group),function(z)head(z,4)));labs<-data.frame(chr=labels$group,start=labels$x-.001,end=labels$x+.001,label=labels$feature,color=labels$color)
links<-list();for(f in unique(circ$feature)){z<-circ[circ$feature==f,];if(nrow(z)>=2){i<-1;j<-nrow(z);links[[length(links)+1]]<-data.frame(feature=f,from=z$group[i],from_x=z$x[i],to=z$group[j],to_x=z$x[j])}}
links<-do.call(rbind,links)
draw_circle<-function(){
 par(mar=c(1,1,1,1),family='sans',cex=1)
 circos.clear();circos.par(start.degree=90,gap.after=c(rep(2,11),20),track.margin=c(0,.008),cell.padding=c(0,0,0,0),points.overflow.warning=FALSE)
 circos.initialize(factors=factor(circ$group,levels=groups),xlim=c(0,1))
 circos.genomicLabels(labs,labels.column=4,side='outside',facing='reverse.clockwise',cex=7/12,col=labs$color,connection_height=convert_height(3,'mm'),line_lwd=.45,labels_height=convert_height(10,'mm'))
 circos.track(factors=circ$group,ylim=c(0,1),track.height=.075,bg.col='#EBEEF0',bg.border='#454C52',panel.fun=function(x,y)circos.text(CELL_META$xcenter,.5,CELL_META$sector.index,facing='bending.inside',niceFacing=TRUE,cex=7/12))
 circos.trackPlotRegion(factors=circ$group,ylim=c(0,1),track.height=.35,bg.border='#454C52',panel.fun=function(x,y){z<-circ[circ$group==CELL_META$sector.index,];circos.segments(z$x,0,z$x,z$score,col=z$color,lwd=.65);circos.points(z$x,z$score,pch=16,col=z$color,cex=.38);if(CELL_META$sector.index==groups[1]){circos.yaxis(side='left',at=c(0,.5,1),labels.cex=7/12,tick.length=convert_length(1,'mm'));circos.text(-.30,.55,'Selection score',facing='reverse.clockwise',niceFacing=TRUE,cex=7/12)}})
 for(i in seq_len(nrow(links)))circos.link(links$from[i],links$from_x[i],links$to[i],links$to_x[i],col=adjustcolor('#4E6A74',.65),lwd=.55)
 circos.clear();legend('bottom',legend=c('Class A','Class B'),col=c('#386A8C','#D58A73'),pch=16,bty='n',horiz=TRUE,cex=7/12,xpd=NA,inset=-.01)
}
p<-ggplotify::as.ggplot(draw_circle)
f1<-'lollipop_scicase126_synthetic_traits_20261029.csv';f2<-'lollipop_scicase126_synthetic_links_20261029.csv';write.csv(circ,file.path(PD,f1),row.names=FALSE);write.csv(links,file.path(PD,f2),row.names=FALSE)
stopifnot(nrow(circ)==288,all(circ$score>=0&circ$score<=1),all(links$feature%in%circ$feature))
